const raw = await Bun.file("src/data/regions/bay-area.jsonc").text();
const stripped = raw.replace(/\/\/.*$/gm, "");
const data = JSON.parse(stripped);
console.log("Parsed OK. region:", data.region);
console.log("items:", data.items.length, "| first:", data.items[0].name);
console.log("seasons:", JSON.stringify(data.items[0].seasons.map(s => `${s.level} ${s.from}-${s.to}`)));
// sanity: weeks in range, non-overlapping, sorted
const secs = data.items[0].seasons;
let ok = true, prevTo = 0;
for (const s of secs) {
  if (s.from < 1 || s.to > 52 || s.from > s.to) ok = false;
  if (s.from <= prevTo) ok = false;
  prevTo = s.to;
}
console.log("range/non-overlap check:", ok ? "PASS" : "FAIL");
'

