echo "=== astro check (strictest typecheck) ==="; bun run check < /dev/null 2>&1 | tail -6
echo; echo "=== validator against real sfbay.jsonc ==="
bun -e '
import { validateRegionData } from "./src/data/validate";
const good = (await import("./src/data/regions/sfbay.jsonc")).default;
console.log("real file:", JSON.stringify(validateRegionData(good)));

// deliberately broken variants
const overlap = structuredClone(good);
overlap.items[0].seasons[1].from = 20; // now overlaps the 18-22 span
console.log("overlap:", JSON.stringify(validateRegionData(overlap).errors));

const badWeek = structuredClone(good);
badWeek.items[0].seasons[0].to = 99;
console.log("bad week:", JSON.stringify(validateRegionData(badWeek).errors));

const noSource = structuredClone(good);
noSource.items[0].sources = [];
console.log("no source:", JSON.stringify(validateRegionData(noSource).errors));

const badLevel = structuredClone(good);
badLevel.items[0].seasons[1].level = "kinda";
console.log("bad level:", JSON.stringify(validateRegionData(badLevel).errors));

const badDate = structuredClone(good);
badDate.generatedAt = "July 2026";
console.log("bad date:", JSON.stringify(validateRegionData(badDate).errors));
'

bun add zod < /dev/null 2>&1 | tail -5
echo "=== version ==="; bun pm ls 2>/dev/null | grep -i "zod@"
echo "=== API probe ==="
bun -e '
import { z } from "zod";
const probe = {};
probe.zEnum = typeof z.enum;
probe.zNativeEnum = typeof z.nativeEnum;
probe.zStringUrl = typeof z.string().url;
probe.zTopUrl = typeof z.url;
probe.zStringDatetime = typeof z.string().datetime;
probe.zIso = typeof z.iso;
probe.zIsoDatetime = (z.iso && typeof z.iso.datetime === "function") ? "fn" : "none";
probe.superRefine = typeof z.object({}).superRefine;
probe.check = typeof z.object({}).check;
// does z.enum accept an as-const object?
let enumObjOk = false;
try { const e = z.enum({A:"a",B:"b"}); e.parse("a"); enumObjOk = true; } catch(err) { enumObjOk = "ERR:"+err.message.slice(0,40); }
probe.enumAcceptsObject = enumObjOk;
console.log(JSON.stringify(probe, null, 2));
'

