export type Region = z.infer<typeof regionSchema>;

export const Availability = {
  Available: 'available',
  Peak: 'peak',
} as const;

const week = z.number().int().min(1).max(52);

const source = z.object({
  title: z.string().min(1),
  url: z.url().nullable(), // null = uncited local knowledge, never a placeholder
});

const season = z.object({
  level: z.enum(Availability),
  from: week, // inclusive
  to: week, //   inclusive; wraps the year when to < from
});

const produce = z.object({
  name: z.string().min(1),
  seasons: z.array(season).superRefine((seasons, ctx) => {
    const claimedBy = new Map<number, number>();
    const reported = new Set<string>();
    seasons.forEach((s, i) => {
      for (const w of weeksCovered(s.from, s.to)) {
        const prev = claimedBy.get(w);
        if (prev === undefined) {
          claimedBy.set(w, i);
          continue;
        }
        const key = `${prev}-${i}`;
        if (reported.has(key)) continue;
        reported.add(key);
        ctx.addIssue({ code: 'custom', message: `overlaps seasons[${prev}] (e.g. week ${w})`, path: [i] });
      }
    });
  }),
  sources: z.array(source).min(1),
});

export const regionSchema = z.object({
  name: z.string().min(1),
  generatedAt: z.iso.datetime(),
  schemaVersion: z.number().int(),
  items: z.array(produce),
});

/** Week numbers a span covers, handling year-wrap (to < from). */
function weeksCovered(from: number, to: number): number[] {
  const weeks: number[] = [];
  if (from <= to) {
    for (let w = from; w <= to; w++) weeks.push(w);
  } else {
    for (let w = from; w <= 52; w++) weeks.push(w);
    for (let w = 1; w <= to; w++) weeks.push(w);
  }
  return weeks;
}

