/**
 * Availability level for a produce item over a span of weeks. The absence of a
 * span means "not at market" — there is no explicit "none" level. Numeric visual
 * weights (e.g. 25 / 100) live in the renderer, not the data.
 */
export type Availability = 'available' | 'peak';

/**
 * Week of the year, 1..52 inclusive (1-indexed, matching how the poster and a
 * human editor both count). We hold to a canonical 52-week year, ignoring the
 * ISO 53rd-week and leap-day subtleties — produce timing isn't that precise.
 * Internal layout math converts to 0-based once, at the load boundary.
 */
export type Week = number;

/**
 * A contiguous span of weeks at a single availability level. `to < from` wraps
 * past week 52 into the new year (e.g. winter citrus). Spans within one item
 * must not overlap.
 */
export interface Season {
  level: Availability;
  /** inclusive */
  from: Week;
  /** inclusive; wraps the year when `to < from` */
  to: Week;
}

/**
 * A real, verifiable reference. `url` is `null` only for genuine local/community
 * knowledge that has no citation — never a synthesized placeholder.
 */
export interface Source {
  title: string;
  url: string | null;
}

export interface ProduceSeasonality {
  /** Plain display name, e.g. "Strawberries". */
  name: string;
  /** Contiguous, non-overlapping spans. Gaps mean "not at market". */
  seasons: Season[];
  /** At least one. */
  sources: Source[];
}

/**
 * A region file. Each file is standalone and shares no data with any other
 * region — there is no shared produce catalog.
 */
export interface RegionData {
  /** Display name of the region, e.g. "San Francisco Bay Area". */
  name: string;
  /** ISO 8601 timestamp; the file is the source of truth, stamped on edit. */
  generatedAt: string;
  schemaVersion: number;
  items: ProduceSeasonality[];
}

