import { describe, test, expect } from 'bun:test';
import { RegionSchema } from '@data/types';

type Span = { level: 'available' | 'peak'; from: number; to: number };

/** A minimal valid region wrapping the given spans in one produce item. */
function regionWith(spans: Span[]): unknown {
  return {
    id: 'test',
    name: 'Test Region',
    generatedAt: '2026-01-01T00:00:00Z',
    schemaVersion: 1,
    items: [{ name: 'Widget', spans, sources: [{ title: 'src', url: null }] }],
  };
}

function isValid(spans: Span[]): boolean {
  return RegionSchema.safeParse(regionWith(spans)).success;
}

function issues(spans: Span[]) {
  const result = RegionSchema.safeParse(regionWith(spans));
  return result.success ? [] : result.error.issues;
}

describe('season span overlap', () => {
  test('adjacent spans do not overlap', () => {
    expect(
      isValid([
        { level: 'available', from: 1, to: 5 },
        { level: 'peak', from: 6, to: 10 },
      ]),
    ).toBe(true);
  });

  test('spans sharing an endpoint overlap', () => {
    expect(
      isValid([
        { level: 'available', from: 1, to: 5 },
        { level: 'peak', from: 5, to: 10 },
      ]),
    ).toBe(false);
  });

  test('a span contained within another overlaps', () => {
    expect(
      isValid([
        { level: 'peak', from: 1, to: 10 },
        { level: 'available', from: 3, to: 5 },
      ]),
    ).toBe(false);
  });

  test('single-week spans are distinct when different, overlapping when equal', () => {
    expect(
      isValid([
        { level: 'peak', from: 1, to: 1 },
        { level: 'available', from: 2, to: 2 },
      ]),
    ).toBe(true);
    expect(
      isValid([
        { level: 'peak', from: 1, to: 1 },
        { level: 'available', from: 1, to: 1 },
      ]),
    ).toBe(false);
  });

  test('a year-wrapping span (to < from) is compared across the wrap', () => {
    // weeks 50..3 cover 50, 51, 52, 1, 2, 3
    expect(
      isValid([
        { level: 'peak', from: 50, to: 3 },
        { level: 'available', from: 10, to: 20 },
      ]),
    ).toBe(true);
    expect(
      isValid([
        { level: 'peak', from: 50, to: 3 },
        { level: 'available', from: 2, to: 8 }, // shares weeks 2, 3
      ]),
    ).toBe(false);
  });

  test('an out-of-range week reports the range error, not a spurious overlap', () => {
    const messages = issues([
      { level: 'peak', from: 1, to: 99 }, // out of range; would bloat weeksCovered without the guard
      { level: 'available', from: 40, to: 45 },
    ]).map((i) => i.message);
    expect(messages.some((m) => m.includes('52'))).toBe(true);
    expect(messages).not.toContain('week spans overlap');
  });

  test('the overlap error is attached to the spans array', () => {
    const overlap = issues([
      { level: 'available', from: 1, to: 5 },
      { level: 'peak', from: 3, to: 8 },
    ]).find((i) => i.message === 'week spans overlap');
    expect(overlap).toBeDefined();
    expect(overlap?.path).toEqual(['items', 0, 'spans']);
  });
});

